      const text = `${graph.nodes.length} services, ${edges.length} call edge(s) over ${range} (${spans.length} spans). Top by volume: ${top}. Worst error rate: ${worst.caller}\u2192${worst.callee} (${pctOf(worst.errorRate)}).`;
